# ABSTRACT: Add an author test that the POD of each module says what each sub takes, returns, and how it fails
# PODNAME: Dist::Zilla::Plugin::Test::Pod::Coverage::More

package Dist::Zilla::Plugin::Test::Pod::Coverage::More;

use 5.036;
use warnings FATAL => q{all};

use Moose;
extends 'Dist::Zilla::Plugin::InlineFiles';
with 'Dist::Zilla::Role::PrereqSource';

=head1 SYNOPSIS

    # The test that the plugin adds, as xt/author/pod-coverage-more.t.
    use Test::More;
    use Test::Pod::Coverage::More;

    all_pod_coverage_more_ok();

=head1 USAGE

In F<dist.ini>:

    [Test::Pod::Coverage::More]

and then run C<dzil test --author>, or C<dzil test --release>, which runs the author tests too.

=head1 DESCRIPTION

Adds F<xt/author/pod-coverage-more.t> to the distribution.  The test runs
C<all_pod_coverage_more_ok> of L<Test::Pod::Coverage::More> over each module of the build.
So it fails for each public sub that the POD does not document,
and for each argument, type, return value and way to fail that the POD of a sub leaves out.

It takes the place of C<[PodCoverageTests]>, which checks only that the POD names each sub.
In a bundle that includes that plugin, such as C<[@TestingMania]>, turn it off:

    [@TestingMania]
    disable = PodCoverageTests

A sub that a C<=for Pod::Coverage> line names counts as documented, as it does for C<[PodCoverageTests]>.

With C<[Blurbs]> of L<Pod::Weaver::Section::Blurbs> in F<weaver.ini>, the build writes the POD of each sub
from the comment above it, and the test reads that POD.

=head1 METHODS

=cut

# Registers Test::Pod::Coverage::More as a requirement of development, as L<Dist::Zilla::Role::PrereqSource> asks,
# at the version of this plugin, which comes in the same distribution.
# @returns nothing
# @example $plugin->register_prereqs;
sub register_prereqs {
    my ($self) = @_;
    $self->zilla->register_prereqs( { type => 'requires', phase => 'develop' }, 'Test::Pod::Coverage::More' => __PACKAGE__->VERSION // 0 );
    return;
}

__PACKAGE__->meta->make_immutable;

1;

=head1 SEE ALSO

L<Test::Pod::Coverage::More>

L<Dist::Zilla::Plugin::PodCoverageTests>

=cut

__DATA__
___[ xt/author/pod-coverage-more.t ]___
#!perl
# This test was generated by Dist::Zilla::Plugin::Test::Pod::Coverage::More.

use strict;
use warnings;

use Test::More;
use Test::Pod::Coverage::More;

all_pod_coverage_more_ok();
